with source as (
    select * from {{ source('ripple_raw', 'FED_EPA_FRS_FULL') }}
)

select
    FRS_FACILITY_DETAIL_REPORT_URL as frs_facility_detail_report_url,
    REGISTRY_ID as registry_id,
    PRIMARY_NAME as primary_name,
    LOCATION_ADDRESS as location_address,
    SUPPLEMENTAL_LOCATION as supplemental_location,
    CITY_NAME as city_name,
    COUNTY_NAME as county_name,
    FIPS_CODE as fips_code,
    STATE_CODE as state_code,
    STATE_NAME as state_name,
    COUNTRY_NAME as country_name,
    POSTAL_CODE as postal_code,
    FEDERAL_FACILITY_CODE as federal_facility_code,
    FEDERAL_AGENCY_NAME as federal_agency_name,
    TRIBAL_LAND_CODE as tribal_land_code,
    TRIBAL_LAND_NAME as tribal_land_name,
    CONGRESSIONAL_DIST_NUM as congressional_dist_num,
    CENSUS_BLOCK_CODE as census_block_code,
    HUC_CODE as huc_code,
    EPA_REGION_CODE as epa_region_code,
    SITE_TYPE_NAME as site_type_name,
    LOCATION_DESCRIPTION as location_description,
    -- FIXED 2026-08-20 (time-index scan): EPA ships these as DD-MON-YY with a
    -- TWO-DIGIT year ('01-MAR-00', '02-JUN-16', '25-SEP-25'). A bare try_to_date
    -- read the year literally, landing all 5,300,149 create dates and 2,782,106
    -- update dates in years 0000-0026. Verified against the raw landing table.
    -- Pivot 2069: EPA's registry postdates 1990, so every 2-digit year is 20xx.
    {{ ripple_ts_from_date('CREATE_DATE', 'dmon2', 2069) }}::date as create_date,
    {{ ripple_ts_from_date('UPDATE_DATE', 'dmon2', 2069) }}::date as update_date,
    US_MEXICO_BORDER_IND as us_mexico_border_ind,
    PGM_SYS_ACRNMS as pgm_sys_acrnms,
    try_to_double(LATITUDE83) as latitude83,
    try_to_double(LONGITUDE83) as longitude83,
    CONVEYOR as conveyor,
    COLLECT_DESC as collect_desc,
    try_to_double(ACCURACY_VALUE) as accuracy_value,
    REF_POINT_DESC as ref_point_desc,
    HDATUM_DESC as hdatum_desc,
    SOURCE_DESC as source_desc
from source
